<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { resourceApi } from '@/api/resource'
import { useAuthStore } from '@/stores/auth'
const auth=useAuthStore();const rows=ref<any[]>([]);const total=ref(0);const loading=ref(false);const drawer=ref(false);const task=ref<any>(null);const details=ref<any[]>([]);const query=reactive({page:1,size:20,sourceType:'',status:''})
async function load(){loading.value=true;try{const d=(await resourceApi.syncTasks(query)).data.data;rows.value=d.items;total.value=d.total}finally{loading.value=false}}
async function show(r:any){task.value=(await resourceApi.syncTask(r.id)).data.data;details.value=(await resourceApi.syncDetails(r.id)).data.data;drawer.value=true}
async function retry(r:any){const {value}=await ElMessageBox.prompt('请输入重试原因','重试同步任务',{inputValidator:v=>!!String(v||'').trim()||'必须填写原因'});const d=(await resourceApi.retrySync(r.id,String(value))).data.data;ElMessage.success(`已生成重试任务 ${d.taskId}`);await load()}
onMounted(load)
</script><template><div class="page"><div><h2>资源同步任务</h2><p>记录基础资源和外部资源的同步过程、标准化结果与失败明细，支持问题追踪和失败任务重试。</p></div><el-card shadow="never"><div class="filters"><el-select v-model="query.sourceType" placeholder="同步类型" clearable><el-option v-for="x in ['CENTOS','ROS','LINE','IP','SUPPLIER']" :key="x" :label="x" :value="x"/></el-select><el-select v-model="query.status" placeholder="状态" clearable><el-option v-for="x in ['PENDING','RUNNING','SUCCESS','PARTIAL_SUCCESS','FAILED','CANCELLED']" :key="x" :label="x" :value="x"/></el-select><el-button type="primary" @click="query.page=1;load()">查询</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="task_no" label="任务编号" min-width="190"/><el-table-column prop="source_type" label="类型" width="100"/><el-table-column prop="supplier_name" label="供应商" min-width="140"/><el-table-column prop="status" label="状态" width="130"/><el-table-column prop="received_count" label="接收" width="80"/><el-table-column prop="normalized_count" label="导入" width="80"/><el-table-column prop="available_count" label="可用" width="80"/><el-table-column prop="triggered_by_name" label="触发人" width="100"/><el-table-column prop="created_at" label="创建时间" min-width="175"/><el-table-column label="操作" width="130" fixed="right"><template #default="s"><el-button link type="primary" @click="show(s.row)">详情</el-button><el-button v-if="auth.hasPermission('resource:sync-task:retry')&&['FAILED','PARTIAL_SUCCESS'].includes(s.row.status)" link type="warning" @click="retry(s.row)">重试</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.page" v-model:page-size="query.size" :total="total" layout="total, sizes, prev, pager, next" @change="load"/></div></el-card><el-drawer v-model="drawer" title="同步任务详情" size="760px"><el-descriptions v-if="task" :column="2" border><el-descriptions-item label="任务编号">{{task.task_no}}</el-descriptions-item><el-descriptions-item label="状态">{{task.status}}</el-descriptions-item><el-descriptions-item label="类型">{{task.source_type}}</el-descriptions-item><el-descriptions-item label="供应商">{{task.supplier_name||'—'}}</el-descriptions-item><el-descriptions-item label="接收">{{task.received_count}}</el-descriptions-item><el-descriptions-item label="导入">{{task.normalized_count}}</el-descriptions-item><el-descriptions-item label="错误" :span="2">{{task.error_message||'—'}}</el-descriptions-item></el-descriptions><el-table :data="details" style="margin-top:16px"><el-table-column prop="source_record_id" label="源记录"/><el-table-column prop="resource_type" label="资源类型"/><el-table-column prop="resource_id" label="资源ID"/><el-table-column prop="process_status" label="处理状态"/><el-table-column prop="available_flag" label="可用"/><el-table-column prop="error_message" label="错误" min-width="180"/></el-table></el-drawer></div></template><style scoped>.page{display:grid;gap:16px}.page h2{margin:0 0 6px}.page p{margin:0;color:#7b8494}.filters{display:flex;gap:10px;margin-bottom:14px}.filters>*{max-width:260px}.pager{display:flex;justify-content:flex-end;margin-top:14px}</style>
